/** Every article: the core's, with each module's (its help.ts) after the article it names, or at the end of its group. */
var ARTICLES = (() => {
	const out = [...CORE_ARTICLES];
	for (const m of help_default) for (const a of m.part) {
		const at = a.after ? out.findIndex((x) => x.id === a.after) : out.map((x) => x.group).lastIndexOf(a.group);
		out.splice(at < 0 ? out.length : at + 1, 0, {
			...a,
			module: m.id
		});
	}
	return out;
})();
var BY_ID = new Map(ARTICLES.map((a) => [a.id, a]));
/** Articles that were renamed: their old ids, from old links and earlier What's new entries, open the new one. */
var MOVED_ARTICLES = {
	"workspace-people": "people",
	"workspace-teams": "teams"
};
var articleById = (id) => BY_ID.get(id) ?? BY_ID.get(MOVED_ARTICLES[id] ?? "");
function textOf(a) {
	return [
		a.title,
		a.summary,
		...a.keywords,
		...a.sections.flatMap((s) => [
			s.heading,
			...s.text ?? [],
			...s.list ?? []
		])
	].join(" ").toLowerCase();
}
var norm = (s) => s.toLowerCase().replace(/[’']/g, "").replace(/[^\p{L}\p{N}-]+/gu, " ").trim();
/**
* Articles where every word of the query appears, best first: in the title, then the keywords, then the summary,
* then anywhere. An empty query returns nothing.
*/
function searchGuide(query) {
	const words = norm(query).split(/\s+/).filter(Boolean);
	if (!words.length) return [];
	return ARTICLES.map((a) => {
		const all = norm(textOf(a));
		if (!textMatches(textOf(a), query)) return null;
		const title = norm(a.title), keys = norm(a.keywords.join(" ")), sum = norm(a.summary);
		return {
			a,
			score: words.reduce((n, w) => n + (title.includes(w) ? 8 : 0) + (keys.includes(w) ? 4 : 0) + (sum.includes(w) ? 2 : 0) + Math.min(4, all.split(w).length - 1), 0)
		};
	}).filter((x) => !!x).sort((x, y) => y.score - x.score || ARTICLES.indexOf(x.a) - ARTICLES.indexOf(y.a)).map((x) => x.a);
}
/** An article as plain text: for the AI assistant. */
function articleText(a) {
	return [
		`# ${a.title}`,
		a.summary,
		...a.sections.map((s) => [
			`## ${s.heading}`,
			...s.text ?? [],
			...(s.list ?? []).map((l) => `- ${l}`)
		].join("\n"))
	].join("\n\n");
}
